int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):100;std::vector<float>x,y;for(int i=0;i<509;i++){x.push_back(float(i%31)/8+.03125f);y.push_back((i%2?-1.f:1.f)*(.5f+float((i/31)%8)/8));}x.insert(x.end(),{0,1.5f,2.5f,3});y.insert(y.end(),{3,1.5f,.5f,0});int n=x.size();std::vector<float>gold(3*n);invkin_cpu(x.data(),y.data(),gold.data(),n);std::vector<double>ind;for(int i=0;i<n;i++){double z[3];for(int j=0;j<3;j++)z[j]=std::max(-30.,std::min(30.,atan2(double(y[i]),double(x[i])-j)*180/acos(-1.)));ind.insert(ind.end(),{z[0],z[1]+2*z[0],z[2]+3*z[1]+6*z[0]});}float *dx,*dy,*da;CU(cudaMalloc(&dx,n*4));CU(cudaMalloc(&dy,n*4));CU(cudaMalloc(&da,3*n*4));CU(cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice));CU(cudaMemcpy(dy,y.data(),n*4,cudaMemcpyHostToDevice));invkin_kernel<<<(n+127)/128,128>>>(dx,dy,da,n);CU(cudaDeviceSynchronize());std::vector<float>prefix={float(n)};prefix.insert(prefix.end(),x.begin(),x.end());prefix.insert(prefix.end(),y.begin(),y.end());for(int trial=1;trial<=5;trial++){CU(cudaDeviceSynchronize());auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)invkin_kernel<<<(n+127)/128,128>>>(dx,dy,da,n);CU(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;std::vector<float>got(3*n);CU(cudaMemcpy(got.data(),da,3*n*4,cudaMemcpyDeviceToHost));double err=0,ecpu=0;bool ok=true;for(int i=0;i<3*n;i++){err=std::max(err,fabs(double(got[i])-ind[i]));ecpu=std::max(ecpu,fabs(double(got[i])-gold[i]));ok&=std::isfinite(got[i]);}ok&=err<=1e-3&&ecpu<=1e-3;auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"source_CPU_max_abs\":%.17g,\"t